// "This is a NAND, and this is what it looks like in silicon." One gate or block shown six ways:
// logic symbol and truth table, transistor schematic, mask layout with dimensions, a 3D view of the
// cell and a cut-line cross-section, for planar, FinFET and nanosheet cells. Geometry comes from
// data/gate_cells.json (generated by gatecells.py and gateblocks.py, which also find the
// shared-diffusion finger order); which transistors conduct comes from the Circuit Lab's logic
// model (physics/logic.js).
import { GATECELLS, REFS } from './data.js';
import { conducts, GATES } from '../physics/logic.js';
import { esc } from './util.js';
import { drawArray, initArray } from './gatearray.js';

const $ = (s) => document.querySelector(s);
const M = { // §9.3 material colours (sim/transistor_sim/crosssection.py)
  si: '#4b596d', sich: '#7b8ca5', oxide: '#8fcfd4', sti: '#6fa9b3', poly: '#c95c50', metal: '#e2b650', highk: '#9a80dc', spacer: '#cfd6e0',
  n: '#3f7fe0', p: '#e07f3f', pwell: '#5f6b52', nwell: '#5a5f7a', al: '#b9c3cd', cu: '#d9825b', sige: '#b58fd6', silicide: '#3b3f48', m2: '#f39ac7',
};
const ON = '#5fd896', E = '#9fc6ff', H = '#ffb37a', AMBER = '#f2b84b', DIM = '#5d6878', INK = '#e8ecf1', MUTED = '#8a94a3';
const MONO = 'font-family="IBM Plex Mono, monospace"';
const state = { gate: 'nand2', tech: 'planar_180', cut: 'n', val: {}, explode: 0.35 };
const GROUPS = [['Basic', ['inv', 'nand2', 'nor2', 'nand3', 'nor3']], ['Compound', ['aoi21', 'oai21', 'aoi22', 'xor2']], ['Blocks', ['fa', 'sram6t']]];
const NAME = { Kb: 'K̄', Sb: 'S̄', Co: 'Cout', QB: 'Q̄', BLB: 'B̄L̄', BLd: 'BL↓', BLBd: 'B̄L̄↓', gnd: 'GND', vdd: 'VDD', C: 'C' };
let NV = {};   // value of every net: inputs, stage outputs, stored bits

const gateOf = () => GATECELLS.gates[state.gate];
const kindOf = () => gateOf().kind;
const sv = (sig) => (sig[0] === '!' ? 1 - NV[sig.slice(1)] : NV[sig]);
const nodeLab = (n) => (n.includes('.') ? `node ${n.split('.').pop()} of the ${NAME[n.split('.')[0]] || n.split('.')[0]} stage` : lab(n));
const lab = (sig) => (sig[0] === '!' ? sig.slice(1) + '̄' : NAME[sig] || (sig.includes('.') ? sig.split('.').pop() : sig));
const isOn = (typ, sig) => (typ === 'n' ? sv(sig) === 1 : sv(sig) === 0);
const inLabel = (x) => (kindOf() === 'fa' && x === 'C' ? 'Cin' : kindOf() === 'sram' && x === 'Q' ? 'Q (stored)' : x);

function evalNets(g) {
  const v = { ...state.val };
  if (g.kind === 'gate') v.Y = conducts(g.pd, v) ? 0 : 1;
  else if (g.kind === 'fa') g.stages.forEach((s) => { v[s.out] = conducts(s.pd, v) ? 0 : 1; });
  else { v.QB = 1 - v.Q; v.BLd = v.WL && !v.Q ? 1 : 0; v.BLBd = v.WL && v.Q ? 1 : 0; }
  return v;
}

export function init() {
  $('#gtPick').innerHTML = GROUPS.map(([name, keys]) => `<span class="gt-glab">${name}</span>`
    + keys.map((k) => `<button type="button" data-g="${k}" aria-pressed="${k === state.gate}">${esc(GATECELLS.gates[k].name)}</button>`).join('')).join('');
  $('#gtTech').innerHTML = Object.entries(GATECELLS.techs).map(([k, t]) => `<button type="button" data-t="${k}" aria-pressed="${k === state.tech}">${esc(t.name)}</button>`).join('');
  $('#gtPick').addEventListener('click', (e) => { const b = e.target.closest('button'); if (!b) return; state.gate = b.dataset.g; press('#gtPick', b); resetInputs(); draw(); });
  $('#gtTech').addEventListener('click', (e) => { const b = e.target.closest('button'); if (!b) return; state.tech = b.dataset.t; press('#gtTech', b); draw(); });
  $('#gtCut').addEventListener('click', (e) => { const b = e.target.closest('button'); if (!b) return; state.cut = b.dataset.c; press('#gtCut', b); draw(); });
  $('#gtInputs').addEventListener('click', (e) => { const b = e.target.closest('button[data-i]'); if (!b) return; state.val[b.dataset.i] ^= 1; draw(); });
  const setRow = (tr) => { gateOf().inputs.forEach((x, k) => { state.val[x] = +tr.dataset.row[k]; }); draw(); };
  $('#gtTruth').addEventListener('click', (e) => { const tr = e.target.closest('tr[data-row]'); if (tr) setRow(tr); });
  $('#gtTruth').addEventListener('keydown', (e) => {
    if (e.key !== 'Enter' && e.key !== ' ') return; const tr = e.target.closest('tr[data-row]'); if (!tr) return;
    e.preventDefault(); const row = tr.dataset.row; setRow(tr); $(`#gtTruth tr[data-row="${row}"]`)?.focus();
  });
  const ex = $('#gtExplode');
  if (ex) ex.addEventListener('input', () => { state.explode = +ex.value; $('#gt3d').innerHTML = iso(gateOf()); });
  initArray(() => drawArray(gateOf(), state.tech));
  resetInputs(); draw();
}

function resetInputs() { state.val = {}; gateOf().inputs.forEach((x) => { state.val[x] = 1; }); if (gateOf().kind === 'sram') state.val.WL = 0; }

function draw() {
  const g = gateOf();
  NV = evalNets(g);
  $('#gtInputs').innerHTML = g.inputs.map((x) => `<button type="button" data-i="${x}" aria-pressed="${state.val[x] === 1}" aria-label="Input ${inLabel(x)} is ${state.val[x]}; press to toggle">${esc(inLabel(x))} = ${state.val[x]}</button>`).join('')
    + g.outputs.map((o) => `<span class="gt-y" data-v="${NV[o]}">${lab(o)} = ${NV[o]}</span>`).join('');
  const key = g.inputs.map((x) => state.val[x]).join('');
  $('#gtTruth').innerHTML = `<thead><tr>${g.inputs.map((x) => `<th>${esc(x === 'C' && g.kind === 'fa' ? 'Cin' : x)}</th>`).join('')}${g.outputs.map((o) => `<th>${lab(o)}</th>`).join('')}</tr></thead><tbody>`
    + g.truth.map(([bits, ys]) => `<tr data-row="${bits.join('')}" class="${bits.join('') === key ? 'on' : ''}" tabindex="0">${bits.map((b) => `<td>${b}</td>`).join('')}${ys.map((y) => `<td><b>${y}</b></td>`).join('')}</tr>`).join('') + '</tbody>';
  $('#gtExpr').innerHTML = g.kind === 'gate' ? `Y = ${esc(GATES[state.gate].fn)}`
    : g.kind === 'fa' ? 'S = A ⊕ B ⊕ Cin <small>Cout = majority(A, B, Cin)</small>' : 'Q̄ = NOT Q <small>WL = 1 connects the cell to the bit lines</small>';
  ['#gtSchem', '#gtLayout', '#gt3d'].forEach((id) => $(id).closest('figure').classList.toggle('gt-full', g.kind === 'fa'));
  $('#gtSymbol').innerHTML = symbol(g);
  $('#gtSchem').innerHTML = schematic(g);
  $('#gtLayout').innerHTML = layoutSvg(g);
  $('#gtDims').innerHTML = dimList(g);
  $('#gt3d').innerHTML = iso(g);
  $('#gtXs').innerHTML = crossSection(g);
  $('#gtSay').innerHTML = explain(g);
  drawArray(g, state.tech);
  const c = g.cells[state.tech], base = g.cells.planar_180, area = c.w * c.h / 1e6;
  const eff = g.effort.g ? Object.values(g.effort.g)[0].toFixed(2) : '—';
  $('#gtSize').innerHTML = `<div><b>${fmtLen(c.w)} × ${fmtLen(c.h)}</b>cell outline</div><div><b>${area < 0.1 ? area.toFixed(4) : area.toFixed(2)} µm²</b>cell area</div>`
    + `<div><b>${state.tech === 'planar_180' ? '1×' : Math.round(base.w * base.h / (c.w * c.h)) + '× smaller'}</b>than the 180 nm cell</div>`
    + (g.kind === 'gate' ? `<div><b>${eff}</b>logical effort per input</div>` : '')
    + `<div><b>${g.effort.n}</b>transistors${state.gate === 'xor2' ? ' (4 in the input inverters)' : ''}</div>`;
  const inputs = g.inputs.map((x) => inLabel(x) + '=' + state.val[x]).join(', '), outs = g.outputs.map((o) => lab(o) + '=' + NV[o]).join(', ');
  const names = { gtSymbol: 'logic symbol', gtSchem: 'transistor schematic', gtLayout: 'mask layout', gt3d: '3D view of the cell', gtXs: 'cross-section' };
  Object.entries(names).forEach(([id, n]) => $('#' + id).setAttribute('aria-label', `${g.name} ${n} in ${GATECELLS.techs[state.tech].name}, inputs ${inputs}, outputs ${outs}`));
}

function explain(g) {
  if (g.kind === 'fa') {
    return `<p><b>Full adder.</b> It adds three bits: S is their sum bit and Cout the carry into the next column. Right now ${state.val.A} + ${state.val.B} + ${state.val.C} = ${NV.Co}${NV.S} in binary.</p>`
      + '<p>This is the 28-transistor mirror adder (<a href="#ref-weste2010">weste2010</a>). The carry stage computes K̄ = NOT majority(A, B, Cin); because majority is its own dual, its pull-up network is the same series/parallel network as the pull-down, mirrored, which is where the name comes from. The sum stage reuses K̄: S̄ = A·B·C + K̄·(A + B + C). Two inverters restore S and Cout. In silicon each stage is one unbroken strip of shared diffusion; stages are separated by a diffusion break, and the inputs reach their gate fingers over the pink metal-2 tracks.</p>';
  }
  if (g.kind === 'sram') {
    const q = state.val.Q, wl = state.val.WL;
    return `<p><b>6T SRAM cell.</b> Two inverters feed each other, so the loop holds one bit: Q = ${q}, Q̄ = ${1 - q}. ${wl ? `The word line is high, so the two access transistors connect the cell to the bit lines; in a read both lines start high and the side storing 0 pulls ${q ? 'B̄L̄' : 'BL'} down.` : 'The word line is low, so the access transistors are off and the cell just holds its bit.'}</p>`
      + '<p>In silicon the nMOS strip is one Euler path: bit line, access transistor, Q, pull-down, ground, pull-down, Q̄, access transistor, bit line. The two pMOS share the supply contact between them. Metal 1 ties each storage node to the gate of the opposite inverter. The pull-down transistors are drawn twice as wide as the access transistors (a cell ratio of 2) so that a read cannot flip the cell (<a href="#ref-seevinck1987">seevinck1987</a>). The 5 nm drawing uses ordinary logic rules; TSMC’s real N5 high-density cell is 0.021 µm² (<a href="#ref-yeap2019">yeap2019</a>), about three times smaller, because memory arrays use special pushed rules.</p>';
  }
  const y = NV.Y;
  const what = {
    inv: 'The output is the opposite of the input.',
    nand2: 'The output is 0 only when A and B are both 1.', nand3: 'The output is 0 only when A, B and C are all 1.',
    nor2: 'The output is 1 only when A and B are both 0.', nor3: 'The output is 1 only when A, B and C are all 0.',
    aoi21: 'AND-OR-INVERT: the output is 0 when A and B are both 1, or when C is 1. One stage of logic where separate gates would need three.',
    oai21: 'OR-AND-INVERT: the output is 0 when C is 1 and at least one of A and B is 1.',
    aoi22: 'The output is 0 when A and B are both 1, or when C and D are both 1.',
    xor2: 'Exclusive OR: the output is 1 when exactly one input is 1. The core is an AOI22 fed with A, B and their complements Ā and B̄, which two small input inverters make.',
  }[state.gate];
  const n = g.order.length, R = g.regions, links = ['n', 'p'].some((t) => R[t].some((r) => r.role === 'link'));
  const words = { s: 'in series', p: 'in parallel' };
  const top = (e) => (typeof e === 'string' ? '' : words[e[0]]);
  let silicon = n === 1 ? 'One nMOS and one pMOS share a single gate finger. The nMOS pulls the output to ground, the pMOS pulls it to the supply.'
    : `${n} gate fingers cross both strips of diffusion, in the order ${g.order.map(lab).join(', ')}. That order is an Euler path through both networks, so neighbouring transistors share a source/drain region and neither strip has to be broken (<a href="#ref-uehara1981">uehara1981</a>). `;
  if (n > 1 && typeof g.pd !== 'string' && g.pd.slice(1).every((c) => typeof c === 'string')) {
    silicon += `The nMOS are ${top(g.pd)} and the pMOS ${top(g.pu)}. ` + (g.pd[0] === 's' ? 'Series transistors are drawn wider so the stack is as strong as one unit transistor.' : 'In a NOR the series pMOS are the weak point, which is why they are drawn widest.');
  }
  if (links) silicon += ' Some internal nodes appear twice along a strip; a pink metal-2 strap joins them over the top.';
  return `<p><b>${esc(g.name)}.</b> ${what} Right now Y = ${y}: ${y ? 'the pMOS network connects the output to the supply' : 'the nMOS network connects the output to ground'}.</p><p>${silicon}</p>`;
}

// ---------- logic symbol ----------
function symbol(g) {
  const wire = (on) => (on ? AMBER : DIM), st = `fill="#1d2530" stroke="${INK}" stroke-width="2.5"`;
  const andP = (x, yc, h) => `<path d="M${x} ${yc - h / 2} H${x + h * 0.5} A${h / 2} ${h / 2} 0 0 1 ${x + h * 0.5} ${yc + h / 2} H${x} Z" ${st}/>`;
  const orP = (x, yc, h) => `<path d="M${x - 6} ${yc - h / 2} Q${x + h * 0.25} ${yc} ${x - 6} ${yc + h / 2} Q${x + h * 0.7} ${yc + h / 2} ${x + h * 1.05} ${yc} Q${x + h * 0.7} ${yc - h / 2} ${x - 6} ${yc - h / 2} Z" ${st}/>`;
  const bub = (x, yc) => `<circle cx="${x + 7}" cy="${yc}" r="7" ${st}/>`;
  const txt = (x, y, t, c = INK, a = 'start', sz = 13) => `<text x="${x}" y="${y}" text-anchor="${a}" font-size="${sz}" fill="${c}" ${MONO}>${t}</text>`;
  const inW = (x, yy, x2, name) => `<line x1="14" y1="${yy}" x2="${x2}" y2="${yy}" stroke="${wire(state.val[name])}" stroke-width="3"/>${txt(4, yy - 6, name)}`;
  const outW = (x, yv = NV.Y) => `<line x1="${x}" y1="70" x2="232" y2="70" stroke="${wire(yv)}" stroke-width="3"/>${txt(218, 62, 'Y')}`;
  const mid = (x1, y1, x2, y2, on) => `<path d="M${x1} ${y1} H${(x1 + x2) / 2} V${y2} H${x2}" fill="none" stroke="${wire(on)}" stroke-width="3"/>`;
  const k = state.gate, v = state.val;
  let s = '';
  if (g.kind === 'fa') {
    s = `<rect x="70" y="18" width="100" height="104" rx="8" ${st}/>${txt(120, 76, 'FA', INK, 'middle', 22)}`
      + ['A', 'B', 'C'].map((x, i) => `<line x1="14" y1="${38 + i * 32}" x2="70" y2="${38 + i * 32}" stroke="${wire(v[x])}" stroke-width="3"/>${txt(4, 32 + i * 32, x === 'C' ? 'Cin' : x, INK, 'start', 12)}`).join('')
      + `<line x1="170" y1="46" x2="232" y2="46" stroke="${wire(NV.S)}" stroke-width="3"/>${txt(206, 38, 'S')}<line x1="170" y1="94" x2="232" y2="94" stroke="${wire(NV.Co)}" stroke-width="3"/>${txt(194, 86, 'Cout', INK, 'start', 12)}`;
  } else if (g.kind === 'sram') {
    const q = v.Q;
    s = `<line x1="24" y1="8" x2="24" y2="132" stroke="${INK}" stroke-width="2"/>${txt(30, 18, 'BL', INK, 'start', 11)}<line x1="216" y1="8" x2="216" y2="132" stroke="${INK}" stroke-width="2"/>${txt(210, 18, 'B̄L̄', INK, 'end', 11)}`
      + `<line x1="10" y1="126" x2="230" y2="126" stroke="${wire(v.WL)}" stroke-width="3"/>${txt(112, 120, 'WL', INK, 'middle', 11)}`
      + `<path d="M96 40 L96 70 L122 55 Z" ${st}/><circle cx="126" cy="55" r="4" ${st}/><path d="M144 100 L144 70 L118 85 Z" ${st}/><circle cx="114" cy="85" r="4" ${st}/>`
      + `<path d="M130 55 H156 V85 H148" fill="none" stroke="${wire(q)}" stroke-width="2.5"/><path d="M110 85 H84 V55 H96" fill="none" stroke="${wire(1 - q)}" stroke-width="2.5"/>`
      + txt(160, 60, `Q=${q}`, q ? AMBER : MUTED, 'start', 11) + txt(80, 100, `Q̄=${1 - q}`, q ? MUTED : AMBER, 'end', 11)
      + `<line x1="24" y1="55" x2="84" y2="55" stroke="${wire(v.WL)}" stroke-dasharray="${v.WL ? '0' : '4 4'}" stroke-width="2"/><line x1="156" y1="85" x2="216" y2="85" stroke="${wire(v.WL)}" stroke-dasharray="${v.WL ? '0' : '4 4'}" stroke-width="2"/>`;
  } else if (k === 'inv') s = inW(0, 70, 80, 'A') + `<path d="M80 35 L80 105 L140 70 Z" ${st}/>` + bub(140, 70) + outW(154);
  else if (['nand2', 'nand3', 'nor2', 'nor3'].includes(k)) {
    const n = g.inputs.length, ys = g.inputs.map((_, i) => 40 + i * (60 / (n - 1)));
    s = g.inputs.map((x, i) => inW(0, ys[i], 92, x)).join('') + (k.startsWith('nand') ? andP(80, 70, 80) : orP(80, 70, 80)) + bub(k.startsWith('nand') ? 160 : 164, 70) + outW(k.startsWith('nand') ? 174 : 178);
  } else if (k === 'aoi21' || k === 'oai21' || k === 'aoi22') {
    const two = k === 'aoi22', first = k === 'oai21' ? orP : andP;
    const ab2 = k === 'oai21' ? (v.A || v.B) : (v.A && v.B), cd = two ? v.C && v.D : v.C;
    s += inW(0, 22, 46, 'A') + inW(0, 48, 46, 'B') + first(40, 35, 44) + mid(84, 35, 130, 58, ab2);
    if (two) s += inW(0, 92, 46, 'C') + inW(0, 118, 46, 'D') + andP(40, 105, 44) + mid(84, 105, 130, 82, cd);
    else s += inW(0, 96, 130, 'C');
    s += (k === 'oai21' ? andP(126, 70, 70) : orP(126, 70, 70)) + bub(k === 'oai21' ? 196 : 198, 70) + outW(k === 'oai21' ? 210 : 212);
  } else if (k === 'xor2') {
    s = inW(0, 48, 96, 'A') + inW(0, 92, 96, 'B') + `<path d="M82 30 Q102 70 82 110" fill="none" stroke="${INK}" stroke-width="2.5"/>` + orP(96, 70, 80) + outW(180);
  }
  return `<svg viewBox="0 0 240 140">${s}</svg>`;
}

// ---------- transistor schematic: series/parallel networks drawn recursively ----------
const U = 76; // horizontal unit per parallel branch
const sz = (e) => (typeof e === 'string' ? { w: 1, h: 1 } : e[0] === 's'
  ? { w: Math.max(...e.slice(1).map((c) => sz(c).w)), h: e.slice(1).reduce((a, c) => a + sz(c).h, 0) }
  : { w: e.slice(1).reduce((a, c) => a + sz(c).w, 0), h: Math.max(...e.slice(1).map((c) => sz(c).h)) });

/** One CMOS stage: pull-up from VDD to the output node, pull-down from it to ground. */
function stageCol(pu, pd, out, cx, yTop, yOut, yBot, stub = 54) {
  const y = NV[out], pullUp = y === 1;
  return `<line x1="${cx}" y1="${yOut}" x2="${cx + stub}" y2="${yOut}" stroke="${y ? AMBER : DIM}" stroke-width="3"/><circle cx="${cx}" cy="${yOut}" r="4" fill="${INK}"/>`
    + `<text x="${stub ? cx + stub + 2 : cx + 8}" y="${stub ? yOut + 4 : yOut - 8}" font-size="12" fill="${INK}" ${MONO}>${lab(out)}=${y}</text>`
    + net(pu, 'p', cx, yTop, yOut, pullUp) + net(pd, 'n', cx, yOut, yBot, !pullUp);
}

function schematic(g) {
  const rails = (W, Ht) => `<line x1="20" y1="24" x2="${W - 50}" y2="24" stroke="${M.p}" stroke-width="3"/><text x="${W - 46}" y="28" font-size="12" fill="#f0a26b" ${MONO}>VDD</text>`
    + `<line x1="20" y1="${Ht - 24}" x2="${W - 50}" y2="${Ht - 24}" stroke="${M.n}" stroke-width="3"/><text x="${W - 46}" y="${Ht - 20}" font-size="12" fill="${E}" ${MONO}>GND</text>`;
  if (g.kind === 'gate' || g.kind === 'fa') {
    const stages = g.kind === 'gate' ? [{ pu: g.pu, pd: g.pd, out: 'Y' }] : g.stages;
    const cols = stages.map((s) => Math.max(sz(s.pu).w, sz(s.pd).w));
    const hUp = Math.max(...stages.map((s) => sz(s.pu).h)), hDn = Math.max(...stages.map((s) => sz(s.pd).h));
    const W = Math.max(300, cols.reduce((a, w) => a + w * U + 110, 60)), Ht = 90 + 70 * (hUp + hDn), yOut = 30 + 70 * hUp + 10;
    let s = rails(W, Ht), x = 60;
    stages.forEach((st, i) => { const cx = x + (cols[i] * U) / 2 + 20; s += stageCol(st.pu, st.pd, st.out, cx, 24, yOut, Ht - 24); x += cols[i] * U + 110; });
    if (state.gate === 'xor2') s += `<text x="12" y="${Ht - 4}" font-size="11" fill="${MUTED}" ${MONO}>Ā, B̄ from two input inverters (not shown)</text>`;
    if (g.kind === 'fa') s += `<text x="12" y="${Ht - 4}" font-size="11" fill="${MUTED}" ${MONO}>mirror stages: the pull-up has the same shape as the pull-down</text>`;
    return `<svg viewBox="0 0 ${W} ${Ht}">${s}</svg>`;
  }
  // 6T SRAM: two cross-coupled inverters between the bit lines, access transistors on the word line
  const W = 480, Ht = 360, yOut = 160, yG = Ht - 80, yWL = Ht - 34, xi = [180, 300], xb = [40, W - 40];
  const wl = state.val.WL;
  let s = `<line x1="120" y1="24" x2="360" y2="24" stroke="${M.p}" stroke-width="3"/><text x="364" y="28" font-size="12" fill="#f0a26b" ${MONO}>VDD</text>`
    + `<line x1="120" y1="${yG}" x2="360" y2="${yG}" stroke="${M.n}" stroke-width="3"/><text x="364" y="${yG + 4}" font-size="12" fill="${E}" ${MONO}>GND</text>`;
  s += stageCol('QB', 'QB', 'Q', xi[0], 24, yOut, yG, 0) + stageCol('Q', 'Q', 'QB', xi[1], 24, yOut, yG, 0);
  s += `<line x1="16" y1="${yWL}" x2="${W - 16}" y2="${yWL}" stroke="${wl ? AMBER : DIM}" stroke-width="3"/><text x="${W / 2}" y="${yWL + 18}" text-anchor="middle" font-size="12" fill="${INK}" ${MONO}>WL = ${wl}</text>`;
  const bl = (x, name) => `<line x1="${x}" y1="22" x2="${x}" y2="${yWL - 14}" stroke="#aab3c0" stroke-width="2.5"/><text x="${x}" y="14" text-anchor="middle" font-size="12" fill="${INK}" ${MONO}>${name}</text>`;
  const access = (x1, x2, active) => {
    const xm = (x1 + x2) / 2, on = wl === 1, col = on ? ON : DIM;
    return `<line x1="${x1}" y1="${yOut}" x2="${xm - 14}" y2="${yOut}" stroke="#aab3c0" stroke-width="2"/><line x1="${xm + 14}" y1="${yOut}" x2="${x2}" y2="${yOut}" stroke="#aab3c0" stroke-width="2"/>`
      + `<line x1="${xm - 14}" y1="${yOut}" x2="${xm + 14}" y2="${yOut}" stroke="${col}" stroke-width="4"/>${on && active ? `<line x1="${x1}" y1="${yOut}" x2="${x2}" y2="${yOut}" stroke="${E}" stroke-width="3" stroke-dasharray="4 5" class="gt-flow"/>` : ''}`
      + `<line x1="${xm - 12}" y1="${yOut + 10}" x2="${xm + 12}" y2="${yOut + 10}" stroke="${INK}" stroke-width="2"/><line x1="${xm}" y1="${yOut + 10}" x2="${xm}" y2="${yWL}" stroke="${INK}" stroke-width="2"/>`;
  };
  s += bl(xb[0], 'BL') + bl(xb[1], 'B̄L̄') + access(xb[0], xi[0], state.val.Q === 0) + access(xi[1], xb[1], state.val.Q === 1);
  s += `<text x="12" y="${Ht - 2}" font-size="11" fill="${MUTED}" ${MONO}>each inverter’s gates are driven by the other inverter’s output</text>`;
  return `<svg viewBox="0 0 ${W} ${Ht}">${s}</svg>`;
}

function net(e, typ, cx, y0, y1, active) {
  const wire = (x1, a, x2, b) => `<line x1="${x1}" y1="${a}" x2="${x2}" y2="${b}" stroke="#aab3c0" stroke-width="2"/>`;
  if (typeof e === 'string') {
    const on = isOn(typ, e), mid = (y0 + y1) / 2, col = on ? ON : DIM;
    const glow = on && active ? `<line x1="${cx}" y1="${y0}" x2="${cx}" y2="${y1}" stroke="${typ === 'n' ? E : H}" stroke-width="3" stroke-dasharray="4 5" class="gt-flow"/>` : '';
    return wire(cx, y0, cx, mid - 14) + wire(cx, mid + 14, cx, y1)
      + `<line x1="${cx}" y1="${mid - 14}" x2="${cx}" y2="${mid + 14}" stroke="${col}" stroke-width="4"/>${glow}`
      + `<line x1="${cx - 10}" y1="${mid - 12}" x2="${cx - 10}" y2="${mid + 12}" stroke="${INK}" stroke-width="2"/>`
      + (typ === 'p' ? `<circle cx="${cx - 16}" cy="${mid}" r="4" fill="none" stroke="${INK}" stroke-width="2"/><line x1="${cx - 20}" y1="${mid}" x2="${cx - 32}" y2="${mid}" stroke="${INK}" stroke-width="2"/>` : `<line x1="${cx - 10}" y1="${mid}" x2="${cx - 32}" y2="${mid}" stroke="${INK}" stroke-width="2"/>`)
      + `<text x="${cx - 36}" y="${mid + 4}" text-anchor="end" font-size="12" fill="${sv(e) ? AMBER : MUTED}" ${MONO}>${lab(e)}</text>`;
  }
  const kids = e.slice(1);
  if (e[0] === 's') {
    const tot = kids.reduce((a, c) => a + sz(c).h, 0);
    let y = y0, s = '';
    kids.forEach((c) => { const y2 = y + (y1 - y0) * sz(c).h / tot; s += net(c, typ, cx, y, y2, active); y = y2; });
    return s;
  }
  const tot = kids.reduce((a, c) => a + sz(c).w, 0);
  let x = cx - (tot * U) / 2, s = '';
  const xs = kids.map((c) => { const xc = x + (sz(c).w * U) / 2; x += sz(c).w * U; return xc; });
  const ya = y0 + 12, yb = y1 - 12;
  s += wire(cx, y0, cx, ya) + wire(cx, yb, cx, y1) + wire(xs[0], ya, xs[xs.length - 1], ya) + wire(xs[0], yb, xs[xs.length - 1], yb);
  kids.forEach((c, i) => { s += net(c, typ, xs[i], ya, yb, active); });
  return s;
}

// ---------- mask layout with dimensions ----------
function layoutSvg(g) {
  const c = g.cells[state.tech], L = GATECELLS.layers, W = c.w > c.h * 1.6 ? 760 : 460, sc = Math.min(W / c.w, 420 / c.h), Hh = c.h * sc;
  const pad = 40, X = (v) => pad + v * sc, Y = (v) => 34 + (c.h - v) * sc;
  const order = ['nwell', 'pselect', 'nselect', 'active', 'fin', 'poly', 'metal1', 'contact', 'via', 'metal2'];
  let s = '<defs><pattern id="gtHatch" width="6" height="6" patternUnits="userSpaceOnUse" patternTransform="rotate(45)"><line x1="0" y1="0" x2="0" y2="6" stroke="#8fb6e0" stroke-width="2" stroke-opacity=".55"/></pattern>'
    + `<marker id="gtArr" viewBox="0 0 8 8" refX="4" refY="4" markerWidth="7" markerHeight="7" orient="auto-start-reverse"><path d="M0 0 L8 4 L0 8 Z" fill="${AMBER}"/></marker></defs>`;
  for (const layer of order) for (const [l, x0, y0, x1, y1] of c.shapes) {
    if (l !== layer) continue;
    const st = L[layer], fill = layer === 'metal1' ? 'url(#gtHatch)' : st.colour;
    s += `<rect x="${X(x0).toFixed(1)}" y="${Y(y1).toFixed(1)}" width="${((x1 - x0) * sc).toFixed(1)}" height="${((y1 - y0) * sc).toFixed(1)}" fill="${fill}" fill-opacity="${layer === 'metal1' ? 1 : st.opacity}" stroke="${st.colour}" stroke-width="1"/>`;
  }
  const th = W > 600 ? 14 : 20, tf = W > 600 ? 10 : 12;
  const tag = (x, y, t, on, stroke) => `<g ${MONO} font-size="${tf}"><rect x="${x - 16}" y="${y - th / 2}" width="32" height="${th}" rx="4" fill="#0c1016" stroke="${stroke || (on ? AMBER : DIM)}"/><text x="${x}" y="${y + tf / 2 - 1}" text-anchor="middle" fill="${stroke ? INK : on ? AMBER : '#aab3c0'}">${t}</text></g>`;
  for (const [name, [px, py]] of Object.entries(c.pins)) s += tag(X(px), Y(py), lab(name), sv(name) === 1);
  for (const [name, [px, py]] of Object.entries(c.outs || {})) s += tag(X(px), Y(py), lab(name), false, INK);
  for (const typ of ['n', 'p']) {
    const yy = Y(c.cut[typ]);
    s += `<line x1="${pad - 6}" y1="${yy}" x2="${X(c.w) + 6}" y2="${yy}" stroke="${typ === state.cut ? '#ffffff' : '#ffffff55'}" stroke-width="${typ === state.cut ? 1.6 : 1}" stroke-dasharray="6 4"/>`
      + `<text x="${X(c.w) + 8}" y="${yy + 4}" font-size="11" ${MONO} fill="${INK}">${typ === 'n' ? 'nMOS' : 'pMOS'} cut</text>`;
  }
  s += `<text x="${X(c.w) + 8}" y="${Y(c.h) + 12}" font-size="11" ${MONO} fill="${MUTED}">VDD</text><text x="${X(c.w) + 8}" y="${Y(0)}" font-size="11" ${MONO} fill="${MUTED}">GND</text>`;
  c.dims.forEach((d, i) => {
    const t = `<tspan fill="${AMBER}">${i + 1}</tspan>`;
    if (d.axis === 'x') {
      const yy = Y(d.at), xa = X(d.a), xb = X(d.b), dy = d.at > c.h / 2 ? -11 : 11;
      s += `<line x1="${xa}" y1="${yy}" x2="${xb}" y2="${yy}" stroke="${AMBER}" stroke-width="1.3" marker-start="url(#gtArr)" marker-end="url(#gtArr)"/>`
        + `<circle cx="${(xa + xb) / 2}" cy="${yy + dy}" r="7" fill="#0c1016" stroke="${AMBER}"/><text x="${(xa + xb) / 2}" y="${yy + dy + 3.5}" text-anchor="middle" font-size="10" ${MONO}>${t}</text>`;
    } else {
      const xx = X(d.at), ya = Y(d.a), yb = Y(d.b);
      s += `<line x1="${xx}" y1="${ya}" x2="${xx}" y2="${yb}" stroke="${AMBER}" stroke-width="1.3" marker-start="url(#gtArr)" marker-end="url(#gtArr)"/>`
        + `<circle cx="${xx - 10}" cy="${(ya + yb) / 2}" r="7" fill="#0c1016" stroke="${AMBER}"/><text x="${xx - 10}" y="${(ya + yb) / 2 + 3.5}" text-anchor="middle" font-size="10" ${MONO}>${t}</text>`;
    }
  });
  const names = { nwell: 'n-well', pselect: 'p⁺ implant', nselect: 'n⁺ implant', active: 'active (diffusion)', fin: 'fins', poly: 'gate', contact: 'contact', metal1: 'metal 1', via: 'via 1', metal2: 'metal 2' };
  const used = order.filter((l) => c.shapes.some((sh) => sh[0] === l));
  if (GATECELLS.techs[state.tech].style === 'gaa') names.active = 'nanosheet stack';
  const cols = W > 600 ? 5 : 3;
  s += used.map((l, i) => `<g transform="translate(${pad + (i % cols) * 170} ${Hh + 86 + Math.floor(i / cols) * 18})"><rect width="11" height="11" fill="${l === 'metal1' ? 'url(#gtHatch)' : L[l].colour}" fill-opacity="${l === 'metal1' ? 1 : L[l].opacity}" stroke="${L[l].colour}"/><text x="16" y="10" font-size="11" ${MONO} fill="${INK}">${names[l]}</text></g>`).join('');
  return `<svg viewBox="0 0 ${W + pad + 90} ${Hh + 90 + Math.ceil(used.length / cols) * 18}">${s}</svg>`;
}

function dimList(g) {
  const c = g.cells[state.tech];
  return c.dims.map((d, i) => `<li><span class="gt-dn">${i + 1}</span>${esc(d.label)}${d.ref && REFS[d.ref] ? ` <a class="gt-ref" href="#ref-${d.ref}" title="${esc(REFS[d.ref].cite)}">${d.ref}</a>` : ''}</li>`).join('');
}

// ---------- 3D view: the layout extruded layer by layer, optionally exploded ----------
function iso(g) {
  const c = g.cells[state.tech], style = GATECELLS.techs[state.tech].style, L = GATECELLS.layers;
  const W = 640, Hh = 430, ex = state.explode * 0.7;
  const Z = style === 'planar'
    ? { active: [0, 0.6, 0], poly: [0.6, 1.6, 1], contact: [0.6, 2.6, 2], metal1: [2.6, 3.2, 3], via: [3.2, 3.8, 4], metal2: [3.8, 4.4, 5] }
    : { fin: [0, 1.4, 0], active: [0, 1.4, 0], poly: [0, 2.0, 1], contact: [1.4, 2.8, 2], metal1: [2.8, 3.3, 3], via: [3.3, 3.8, 4], metal2: [3.8, 4.3, 5] };
  const span = Math.max(c.w, c.h), s0 = 380 / span, zU = 0.05 * Math.min(span, 2.2 * Math.min(c.w, c.h));
  const cs = Math.cos(Math.PI / 6), sn = 0.5;
  const bb = [Infinity, Infinity, -Infinity, -Infinity];
  const P = (x, y, z) => {
    const q = [W / 2 + (x - (c.h - y)) * cs * s0 * 0.78 + (c.h - c.w) * cs * s0 * 0.39, 120 + (x + (c.h - y)) * sn * s0 * 0.78 - z * zU * s0];
    bb[0] = Math.min(bb[0], q[0]); bb[1] = Math.min(bb[1], q[1]); bb[2] = Math.max(bb[2], q[0]); bb[3] = Math.max(bb[3], q[1]);
    return q;
  };
  // frame the model at its fully exploded extent, so dragging the slider does not rescale the view
  for (const [x, y] of [[0, 0], [c.w, 0], [c.w, c.h], [0, c.h]]) for (const z of [-1.2, 4.4 + 0.7 * 5 * 1.6]) P(x, y, z);
  const pt = (a) => a.map((v) => v.toFixed(1)).join(',');
  const quad = (pts, fill, op = 1, stroke = 'none') => `<polygon points="${pts.map(pt).join(' ')}" fill="${fill}" fill-opacity="${op}" stroke="${stroke}" stroke-width=".6"/>`;
  const shadeC = (hex, k) => { const n = parseInt(hex.slice(1), 16); return `rgb(${[n >> 16, (n >> 8) & 255, n & 255].map((v) => Math.min(255, Math.round(v * k))).join(',')})`; };
  const box = (x0, y0, x1, y1, z0, z1, col, op) => quad([P(x0, y0, z1), P(x1, y0, z1), P(x1, y1, z1), P(x0, y1, z1)], col, op, shadeC(col, 1.25))
    + quad([P(x0, y0, z0), P(x1, y0, z0), P(x1, y0, z1), P(x0, y0, z1)], shadeC(col, 0.72), op)
    + quad([P(x1, y0, z0), P(x1, y1, z0), P(x1, y1, z1), P(x1, y0, z1)], shadeC(col, 0.55), op);
  let s = '';
  s += box(0, 0, c.w, c.h, -1.2, 0, M.si, 1);
  for (const [l, x0, y0, x1, y1] of c.shapes) if (l === 'nwell') s += quad([P(x0, y0, 0.01), P(x1, y0, 0.01), P(x1, y1, 0.01), P(x0, y1, 0.01)], M.nwell, 0.85);
  s += quad([P(0, 0, 0.01), P(c.w, 0, 0.01), P(c.w, c.h, 0.01), P(0, c.h, 0.01)], M.sti, 0.12);
  const col = (l) => ({ active: style === 'gaa' ? M.sich : '#3aa66e', fin: M.sich, poly: style === 'planar' ? M.poly : M.metal, contact: '#c9d1db', metal1: '#8fb6e0', via: INK, metal2: M.m2 }[l] || L[l]?.colour || '#888');
  const fingers = c.fingers || [];
  const layers = Object.keys(Z).sort((a, b) => Z[a][0] - Z[b][0] || Z[a][2] - Z[b][2]);
  for (const l of layers) {
    const [z0, z1, k] = Z[l], dz = ex * k * 1.6;
    const shp = c.shapes.filter((sh) => sh[0] === l).sort((a, b) => (a[3] - (c.h - a[2])) - (b[3] - (c.h - b[2])) || a[1] - b[1]);
    const op = l === 'metal1' || l === 'metal2' ? 0.9 : 1;
    for (const [, x0, y0, x1, y1] of shp) {
      const on = l === 'poly' && fingers.some(([fx, sig]) => fx >= x0 && fx <= x1 && sv(sig) === 1);
      s += box(x0, y0, x1, y1, z0 + dz, z1 + dz, on ? (style === 'planar' ? '#ff8a6b' : '#fff1b0') : col(l), op);
    }
  }
  const tag = { active: style === 'gaa' ? 'nanosheets' : 'diffusion', fin: 'fins', poly: style === 'planar' ? 'poly gate' : 'metal gate', contact: 'contacts', metal1: 'metal 1', via: 'via 1', metal2: 'metal 2' };
  const present = layers.filter((l) => c.shapes.some((sh) => sh[0] === l));
  // fit the view to the model, with the layer key in a column beside it (no leader lines across the cell)
  const vx = bb[0] - 18, vy = bb[1] - 40, lx = bb[2] + 26, vw = lx + 120 - vx, vh = Math.max(bb[3] + 18 - vy, 40 + present.length * 22);
  let key = '';
  present.forEach((l, i) => {
    const ly = vy + 50 + i * 22;
    key += `<rect x="${lx}" y="${ly - 9}" width="11" height="11" fill="${col(l)}" stroke="${shadeC(col(l), 1.25)}"/><text x="${lx + 17}" y="${ly + 1}" font-size="12" ${MONO} fill="${INK}">${tag[l]}</text>`;
  });
  const bg = `<defs><radialGradient id="gtFloor" cx="45%" cy="45%" r="70%"><stop offset="0" stop-color="#1b2431"/><stop offset="1" stop-color="#0c1016"/></radialGradient></defs><rect x="${vx}" y="${vy}" width="${vw}" height="${vh}" fill="url(#gtFloor)"/>`;
  const title = `<text x="${vx + 12}" y="${vy + 20}" font-size="11" ${MONO} fill="${MUTED}">${esc(g.name)} · ${esc(GATECELLS.techs[state.tech].name)} · heights not to scale · lit gates are inputs at 1</text>`;
  return `<svg viewBox="${vx.toFixed(1)} ${vy.toFixed(1)} ${vw.toFixed(1)} ${vh.toFixed(1)}">${bg}${s}${key}${title}</svg>`;
}

// ---------- cut-line cross-section ----------
function crossSection(g) {
  const typ = state.cut, regs = g.regions[typ], style = GATECELLS.techs[state.tech].style;
  const many = regs.filter((r) => r.kind === 'sd').length > 7;
  const sd = many ? 48 : 64, gw = style === 'planar' ? (many ? 28 : 34) : (many ? 26 : 30), sti = 40, brk = 44;
  const total = regs.reduce((a, r) => a + (r.kind === 'sd' ? sd : r.kind === 'gate' ? gw : brk), 0) + 2 * sti;
  const W = Math.max(680, total + 100), ks = Math.max(1, W / 860), x0 = (W - total) / 2;
  const fs = (n) => Math.round(n * ks);
  const sub = typ === 'n' ? M.pwell : M.nwell, dop = typ === 'n' ? M.n : style === 'planar' ? M.p : M.sige, carrier = typ === 'n' ? E : H;
  const ySi = style === 'planar' ? 236 : 262, yM1 = 92, yM2 = 50;
  const Hh = Math.round((style === 'planar' ? ySi + 40 : ySi + 64) + 100 * ks), yBox = Hh - 100 * ks;
  let s = `<defs><linearGradient id="gtSub" x1="0" y1="0" x2="0" y2="1"><stop offset="0" stop-color="${sub}"/><stop offset="1" stop-color="${M.si}"/></linearGradient></defs>`;
  s += `<rect width="${W}" height="${Hh}" fill="#0c1016"/>`;
  s += `<rect x="0" y="${ySi}" width="${W}" height="${Hh - ySi}" fill="url(#gtSub)"/>`;
  s += `<rect x="0" y="${yM1 - 8}" width="${W}" height="${ySi - yM1 + 8}" fill="${M.oxide}" opacity=".09"/><rect x="0" y="${yM2 - 8}" width="${W}" height="${yM1 - yM2}" fill="${M.oxide}" opacity=".05"/>`;
  s += `<line x1="0" y1="${yM1 - 8}" x2="${W}" y2="${yM1 - 8}" stroke="${M.oxide}" stroke-opacity=".25" stroke-dasharray="3 4"/>`;
  s += `<text x="10" y="${yM1 + 8}" font-size="${fs(10)}" ${MONO} fill="${MUTED}">ILD</text>`;
  const stiH = style === 'planar' ? 46 : 70, stiY = ySi - (style === 'planar' ? 4 : 30);
  const stiBlock = (x, w) => `<rect x="${x}" y="${stiY}" width="${w}" height="${stiH}" fill="${M.sti}"/>`;
  s += stiBlock(x0 - 30, sti + 30) + stiBlock(x0 + total - sti, sti + 30);
  s += `<text x="${x0 - 14}" y="${stiY + stiH - 8}" font-size="${fs(10)}" ${MONO} fill="#0a0d11">STI</text>`;
  // the FinFET fin body under each run of diffusion
  if (style === 'finfet') {
    let xa = x0 + sti, xx = xa;
    regs.forEach((r, i) => {
      const w = r.kind === 'sd' ? sd : r.kind === 'gate' ? gw : brk;
      if (r.kind === 'break') { s += `<rect x="${xa - 6}" y="${ySi - 56}" width="${xx - xa + 12}" height="56" fill="${M.sich}"/>`; xa = xx + w; }
      xx += w;
      if (i === regs.length - 1) s += `<rect x="${xa - 6}" y="${ySi - 56}" width="${xx - xa + 12}" height="56" fill="${M.sich}"/>`;
    });
  }
  let x = x0 + sti;
  const contacts = [], straps = {};
  regs.forEach((r) => {
    if (r.kind === 'break') {
      s += stiBlock(x + 4, brk - 8) + (style === 'planar' ? '' : `<rect x="${x + brk / 2 - gw / 2}" y="${ySi - 126}" width="${gw}" height="${126 - (ySi - stiY)}" fill="${M.metal}" opacity=".45"/>`);
      x += brk;
      return;
    }
    if (r.kind === 'gate') {
      const on = isOn(typ, r.input), lbl = `${lab(r.input)}=${sv(r.input)}`;
      if (style === 'planar') {
        s += `<rect x="${x - 9}" y="${ySi - 70}" width="9" height="70" fill="${M.spacer}"/><rect x="${x + gw}" y="${ySi - 70}" width="9" height="70" fill="${M.spacer}"/>`;
        s += `<rect x="${x}" y="${ySi - 5}" width="${gw}" height="5" fill="${M.oxide}"/><rect x="${x}" y="${ySi - 70}" width="${gw}" height="65" fill="${M.poly}"/><rect x="${x}" y="${ySi - 74}" width="${gw}" height="5" fill="${M.silicide}"/>`;
        s += `<rect x="${x - 9}" y="${ySi}" width="9" height="7" fill="${dop}" opacity=".55"/><rect x="${x + gw}" y="${ySi}" width="9" height="7" fill="${dop}" opacity=".55"/>`;
        if (on) s += `<rect x="${x}" y="${ySi}" width="${gw}" height="4" fill="${carrier}" class="gt-ch"/>`;
      } else if (style === 'finfet') {
        s += `<rect x="${x - 7}" y="${ySi - 116}" width="7" height="60" fill="${M.spacer}"/><rect x="${x + gw}" y="${ySi - 116}" width="7" height="60" fill="${M.spacer}"/>`;
        s += `<rect x="${x}" y="${ySi - 118}" width="${gw}" height="62" fill="${M.highk}"/><rect x="${x + 3}" y="${ySi - 118}" width="${gw - 6}" height="59" fill="${M.metal}"/><rect x="${x}" y="${ySi - 126}" width="${gw}" height="8" fill="${M.spacer}" opacity=".7"/>`;
        if (on) s += `<rect x="${x}" y="${ySi - 56}" width="${gw}" height="4" fill="${carrier}" class="gt-ch"/>`;
      } else {
        s += `<rect x="${x}" y="${ySi - 120}" width="${gw}" height="120" fill="${M.highk}"/><rect x="${x + 3}" y="${ySi - 120}" width="${gw - 6}" height="117" fill="${M.metal}"/><rect x="${x}" y="${ySi - 128}" width="${gw}" height="8" fill="${M.spacer}" opacity=".7"/>`;
        s += `<rect x="${x - 7}" y="${ySi - 134}" width="7" height="32" fill="${M.spacer}"/><rect x="${x + gw}" y="${ySi - 134}" width="7" height="32" fill="${M.spacer}"/>`;
        for (let k = 0; k < 3; k++) {
          const ys = ySi - 26 - k * 30;
          s += `<rect x="${x - 6}" y="${ys}" width="${gw + 12}" height="12" fill="${M.sich}"/>`;
          s += `<rect x="${x - 6}" y="${ys + 12}" width="6" height="18" fill="${M.spacer}"/><rect x="${x + gw}" y="${ys + 12}" width="6" height="18" fill="${M.spacer}"/>`;
          if (on) s += `<rect x="${x}" y="${ys + 4}" width="${gw}" height="4" fill="${carrier}" class="gt-ch"/>`;
        }
      }
      s += `<text x="${x + gw / 2}" y="${style === 'planar' ? ySi - 80 : ySi - 140}" text-anchor="middle" font-size="${fs(many ? 10 : 12)}" ${MONO} fill="${sv(r.input) ? AMBER : MUTED}">${lbl}</text>`;
      x += gw;
      return;
    }
    const cx = x + sd / 2;
    let yTop;
    if (style === 'planar') {
      s += `<path d="M${x - 6} ${ySi} H${x + sd + 6} V${ySi + 20} Q${x + sd + 6} ${ySi + 30} ${x + sd - 4} ${ySi + 30} H${x + 4} Q${x - 6} ${ySi + 30} ${x - 6} ${ySi + 20} Z" fill="${dop}"/>`;
      s += `<rect x="${x + 2}" y="${ySi - 4}" width="${sd - 4}" height="4" fill="${M.silicide}"/>`;
      yTop = ySi - 4;
    } else {
      const top = style === 'finfet' ? ySi - 84 : ySi - 114;
      s += `<path d="M${x + 1} ${ySi} L${x + 1} ${top + 18} L${cx} ${top} L${x + sd - 1} ${top + 18} L${x + sd - 1} ${ySi} Z" fill="${dop}"/>`;
      s += `<path d="M${x + 8} ${top + 14} L${cx} ${top + 3} L${x + sd - 8} ${top + 14}" fill="none" stroke="${M.silicide}" stroke-width="4"/>`;
      yTop = top + 6;
    }
    if (r.role !== 'internal') {
      const cw = style === 'planar' ? 18 : 16, mw = many ? 40 : 52;
      s += `<rect x="${cx - cw / 2 - 2}" y="${yM1 + 14}" width="${cw + 4}" height="${yTop - yM1 - 14}" fill="#8b6f4e"/><rect x="${cx - cw / 2}" y="${yM1 + 14}" width="${cw}" height="${yTop - yM1 - 14}" fill="${M.al}"/>`;
      s += `<rect x="${cx - mw / 2}" y="${yM1}" width="${mw}" height="16" fill="${M.cu}" stroke="#8b6f4e"/>`;
      contacts.push([cx, r.role === 'rail' ? (r.node === 'gnd' ? 'GND' : 'VDD') : lab(r.node), r.role]);
      if (r.role === 'link' || r.role === 'bitline') (straps[r.node] ||= []).push(cx);
    }
    x += sd;
  });
  // metal 2 above: straps that join repeated nodes, and the SRAM bit lines
  Object.entries(straps).forEach(([node, xs]) => {
    const bitline = node.startsWith('BL');
    xs.forEach((cx) => { s += `<rect x="${cx - 8}" y="${yM2 + 14}" width="16" height="${yM1 - yM2 - 14}" fill="${INK}" opacity=".85"/>`; });
    s += `<rect x="${Math.min(...xs) - 26}" y="${yM2}" width="${Math.max(...xs) - Math.min(...xs) + 52}" height="16" fill="${M.m2}" stroke="#8b6f4e"/>`;
    s += `<text x="${(Math.min(...xs) + Math.max(...xs)) / 2}" y="${yM2 - 6}" text-anchor="middle" font-size="${fs(11)}" ${MONO} fill="${M.m2}">${bitline ? `bit line ${lab(node)} (metal 2)` : xs.length > 1 ? `strap joins ${nodeLab(node)}` : nodeLab(node)}</text>`;
  });
  contacts.forEach(([cx, lbl, role]) => { if (role !== 'link' && role !== 'bitline') s += `<text x="${cx}" y="${yM1 - 6}" text-anchor="middle" font-size="${fs(many ? 10 : 12)}" ${MONO} fill="${role === 'out' || role === 'storage' ? INK : '#aab3c0'}">${lbl}</text>`; });
  const legend = style === 'planar'
    ? [['poly', 'polysilicon gate'], ['oxide', 'gate oxide'], ['spacer', 'spacer'], ['silicide', 'silicide'], [typ === 'n' ? 'n' : 'p', typ === 'n' ? 'n⁺ source/drain' : 'p⁺ source/drain'], ['al', 'tungsten contact'], ['cu', 'metal 1'], ['sti', 'trench isolation']]
    : [['metal', 'metal gate'], ['highk', 'high-k'], ['spacer', style === 'gaa' ? 'spacers, inner spacers' : 'spacer'], ['sich', style === 'gaa' ? 'Si nanosheets' : 'Si fin'], [typ === 'n' ? 'n' : 'sige', typ === 'n' ? 'n⁺ epi source/drain' : 'SiGe p⁺ epi source/drain'], ['silicide', 'silicide'], ['al', 'contact'], ['cu', 'metal 1']];
  if (Object.keys(straps).length) legend.push(['m2', 'metal 2']);
  legend.push(['carrier', `${typ === 'n' ? 'electron' : 'hole'} channel (gate on)`]);
  s += `<rect x="0" y="${yBox}" width="${W}" height="${100 * ks}" fill="#0c1016" opacity=".85"/>`;
  s += legend.map(([k, t], i) => `<g transform="translate(${12 + (i % 3) * 222 * ks} ${yBox + 32 * ks + Math.floor(i / 3) * 17 * ks})"><rect width="${10 * ks}" height="${10 * ks}" fill="${k === 'carrier' ? carrier : M[k]}"/><text x="${15 * ks}" y="${9 * ks}" font-size="${fs(11)}" ${MONO} fill="${INK}">${t}</text></g>`).join('');
  s += `<text x="12" y="${yBox + 18 * ks}" font-size="${fs(11)}" ${MONO} fill="${MUTED}">${typ === 'n' ? 'nMOS strip in the p-well' : 'pMOS strip in the n-well'}, cut along the dashed line · ${esc(GATECELLS.techs[state.tech].name)} · not to scale${regs.some((r) => r.kind === 'break') ? ' · stages separated by diffusion breaks' : ''}</text>`;
  return `<svg viewBox="0 0 ${W} ${Hh}" style="${W > 700 ? `max-width:none;--mw:${Math.round(W * 0.8)}px` : ''}">${s}</svg>`;
}

const fmtLen = (nm) => (nm >= 1000 ? (nm / 1000).toFixed(2) + ' µm' : nm.toFixed(0) + ' nm');
function press(sel, b) { document.querySelectorAll(`${sel} button`).forEach((x) => x.setAttribute('aria-pressed', String(x === b))); }
